/**
 * Text for the chart drawer, without a DOM: widths come from tables measured from the site's font files
 * (./metrics.ts, regenerated by tools/measure-fonts.ts), so the server and the browser lay out the same SVG.
 */
import { METRICS, METRIC_CHARS } from "./metrics";

/** Figures (Neue Montreal) and labels (Satoshi): the next/font variables from the root layout, falling back to the
 * family names (an undefined var() without a fallback would void the whole declaration). */
export const FIG_FAMILY =
  'var(--font-neue-montreal, "Neue Montreal"), "Helvetica Neue", Arial, sans-serif';
export const SANS_FAMILY =
  'var(--font-satoshi, Satoshi), "Helvetica Neue", Arial, sans-serif';

export type Face = "sans" | "fig";

const INDEX = new Map<string, number>(
  Array.from(METRIC_CHARS).map((ch, i) => [ch, i]),
);

/** Width in px of `s` at `fs` px. `ls` is letter-spacing in em (figures are drawn tighter). */
export function textWidth(
  s: string | number,
  fs: number,
  weight = 400,
  face: Face = "sans",
  ls = 0,
): number {
  const table =
    face === "fig"
      ? METRICS.fig500
      : weight >= 700
        ? METRICS.sans700
        : weight >= 500
          ? METRICS.sans500
          : METRICS.sans400;
  const fallback = table[INDEX.get("n") ?? 0];
  let units = 0;
  let n = 0;
  for (const ch of String(s)) {
    const i = INDEX.get(ch);
    units += i === undefined ? fallback : table[i];
    n += 1;
  }
  return (units / 1000) * fs + n * ls * fs;
}

/** Escapes a value for SVG text or an attribute. Every text value the drawer writes passes through here. */
export function esc(s: string | number): string {
  return String(s)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

/** Greedy word wrap at `maxW`. A single word wider than the line keeps its own line. */
export function wrap(
  s: string,
  maxW: number,
  fs: number,
  weight = 400,
): string[] {
  const out: string[] = [];
  let cur = "";
  for (const word of String(s).split(" ")) {
    const t = cur ? `${cur} ${word}` : word;
    if (cur && textWidth(t, fs, weight) > maxW) {
      out.push(cur);
      cur = word;
    } else cur = t;
  }
  if (cur) out.push(cur);
  return out.length ? out : [""];
}

/**
 * Word wrap whose two-line results are balanced: "Clicked by / day 28", never "Clicked by day / 28". Used by the thin
 * card charts (design-lab/research-home-2026-11-03/kit/charts-v2-thin.js); the default charts keep the greedy wrap.
 */
export function wrapBalanced(
  s: string,
  maxW: number,
  fs: number,
  weight = 400,
): string[] {
  const out = wrap(s, maxW, fs, weight);
  if (out.length !== 2) return out;
  const words = String(s).split(" ");
  let best = out;
  let bw = Infinity;
  for (let k = 1; k < words.length; k++) {
    const a = words.slice(0, k).join(" ");
    const b = words.slice(k).join(" ");
    const m = Math.max(textWidth(a, fs, weight), textWidth(b, fs, weight));
    if (m <= maxW && m < bw) {
      bw = m;
      best = [a, b];
    }
  }
  return best;
}

/** One decimal place for coordinates. */
export const r1 = (n: number): number => Math.round(n * 10) / 10;
export const nf = (v: number | string): string =>
  Number(v).toLocaleString("en-US");
export const pct = (v: number): string => `${Number(v).toFixed(1)}%`;

export interface TextOpts {
  fs: number;
  c: string;
  w?: number;
  a?: "start" | "middle" | "end";
  /** A figure: Neue Montreal, tight. */
  fig?: boolean;
  ls?: string;
  /** The string is already escaped markup (a <tspan>). */
  raw?: boolean;
  extra?: string;
}

export function T(
  x: number,
  y: number,
  s: string | number,
  o: TextOpts,
): string {
  const a = o.a && o.a !== "start" ? ` text-anchor="${o.a}"` : "";
  const fam = o.fig
    ? ` style="font-family:${esc(FIG_FAMILY)}" letter-spacing="${o.ls ?? "-0.02em"}"`
    : o.ls
      ? ` letter-spacing="${o.ls}"`
      : "";
  return `<text x="${r1(x)}" y="${r1(y)}"${a} font-size="${o.fs}" font-weight="${o.w ?? 400}" fill="${o.c}"${fam}${o.extra ?? ""}>${o.raw ? s : esc(s)}</text>`;
}

/** Width of a figure string as T draws it (Neue Montreal at -0.02em unless given). */
export const figWidth = (s: string, fs: number, ls = -0.02): number =>
  textWidth(s, fs, 500, "fig", ls);
